from pybricks.hubs import PrimeHub
from pybricks.parameters import Button, Direction, Port
from pybricks.pupdevices import ColorSensor, Motor
from pybricks.robotics import DriveBase
from pybricks.tools import wait

# Set up.
right_wheel = Motor(Port.B, Direction.CLOCKWISE)
left_wheel = Motor(Port.F, Direction.COUNTERCLOCKWISE)
Green = DriveBase(left_wheel, right_wheel, 56, 140)
Left_motor = Motor(Port.E, Direction.CLOCKWISE)
Right_motor = Motor(Port.A, Direction.CLOCKWISE)
Left_color_sensor = ColorSensor(Port.D)
Right_color_sensor = ColorSensor(Port.C)
prime_hub = PrimeHub()

def Pass_ant_root():
    Green.settings(straight_speed=250)
    Green.arc(700, angle=90)
    Green.straight(300)
    Green.arc(50, angle=45)
    Green.straight(160)
    Green.turn(-70)
    # Push ant
    Green.settings(straight_speed=100)
    Green.straight(130)
    Green.settings(straight_speed=200)
    Green.straight(-60)
    Green.turn(90)
    Green.settings(straight_speed=300)
    Green.straight(550)
    Green.turn(40)
    Green.straight(400)


# The main program starts here.
while not Button.LEFT in prime_hub.buttons.pressed():
    wait(0)
wait(200)
Pass_ant_root()
# Use tree jig
